import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.DUS-qonf.js";const m=JSON.parse('{"title":"Wire format","description":"","frontmatter":{},"headers":[],"relativePath":"reference/wire-format.md","filePath":"reference/wire-format.md","lastUpdated":1793170889000}'),r={name:"reference/wire-format.md"};function c(i,e,s,n,l,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="wire-format" tabindex="-1">Wire format <a class="header-anchor" href="#wire-format" aria-label="Permalink to &quot;Wire format&quot;">​</a></h1><p>How values travel as JSON between RustCMS and its clients: the admin panel&#39;s API, values given to <a href="./../admin/custom-fields.html">custom widgets</a>, and the JSON that <code>make:api</code> generates. Read it when you write a client, a test or a custom widget. The rule: never lose precision.</p><h2 id="kinds" tabindex="-1">Kinds <a class="header-anchor" href="#kinds" aria-label="Permalink to &quot;Kinds&quot;">​</a></h2><p>Every column the admin exposes gets a kind from its SeaORM column type. The schema sends the kind as each field&#39;s <code>valueType</code>.</p><table tabindex="0"><thead><tr><th>Kind</th><th><code>valueType</code></th><th>Column types</th><th>JSON</th></tr></thead><tbody><tr><td><code>String</code></td><td><code>string</code></td><td><code>char</code>, <code>varchar</code>, <code>text</code></td><td>string</td></tr><tr><td><code>I32</code></td><td><code>i32</code></td><td><code>integer</code></td><td>number</td></tr><tr><td><code>I64</code></td><td><code>i64</code></td><td><code>bigint</code></td><td><strong>string</strong> (JavaScript numbers lose precision past 2⁵³)</td></tr><tr><td><code>F64</code></td><td><code>f64</code></td><td><code>float</code>, <code>double</code></td><td>number</td></tr><tr><td><code>Bool</code></td><td><code>bool</code></td><td><code>boolean</code></td><td>boolean</td></tr><tr><td><code>Decimal</code></td><td><code>decimal</code></td><td><code>decimal(p, s)</code>, <code>money</code></td><td><strong>string</strong>, at the column scale (<code>&quot;10.50&quot;</code>)</td></tr><tr><td><code>Uuid</code></td><td><code>uuid</code></td><td><code>uuid</code></td><td>lowercase hyphenated string</td></tr><tr><td><code>Date</code></td><td><code>date</code></td><td><code>date</code></td><td><code>&quot;YYYY-MM-DD&quot;</code></td></tr><tr><td><code>LocalDateTime</code></td><td><code>local_datetime</code></td><td><code>datetime</code>, <code>timestamp</code></td><td><code>&quot;YYYY-MM-DDTHH:MM:SS[.fff]&quot;</code>, no time zone</td></tr><tr><td><code>Instant</code></td><td><code>instant</code></td><td><code>timestamp with time zone</code></td><td>RFC 3339; accepted with any offset, written in UTC (<code>Z</code>)</td></tr><tr><td><code>Json</code></td><td><code>json</code></td><td><code>json</code>, <code>jsonb</code></td><td>any JSON</td></tr></tbody></table><p>Decimals are rounded and rescaled to the column&#39;s scale before they are sent, so a value reads the same on every database (SQLite, which stores decimals as REAL, would otherwise drop trailing zeros).</p><h2 id="decoding" tabindex="-1">Decoding <a class="header-anchor" href="#decoding" aria-label="Permalink to &quot;Decoding&quot;">​</a></h2><p>Decoding is strict: a value of the wrong JSON shape is a 422 on its field, never a silent conversion.</p><ul><li>A number sent for an <code>I64</code> field, or a decimal sent as a number, is refused (<code>must be a string</code>).</li><li>An <code>I32</code> value outside the 32-bit range is <code>out of range</code>.</li><li><code>null</code> is accepted only for nullable columns.</li><li>In a query string (list filters, <code>filter[price][gte]=10</code>), every value is text: <code>I32</code>, <code>F64</code>, <code>Bool</code> and <code>Json</code> values are parsed from it, the others are read as the strings they already are. See <a href="./admin-api.html#lists">Admin API: lists</a>.</li></ul><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><p>Record keys are always strings in URLs and envelopes (<code>&quot;42&quot;</code>, a UUID, or a natural key). A primary key must be an <code>integer</code>, <code>bigint</code>, text or <code>uuid</code> column, and a single column: a resource on anything else stops the boot.</p><h2 id="values-that-never-travel-as-such" tabindex="-1">Values that never travel as such <a class="header-anchor" href="#values-that-never-travel-as-such" aria-label="Permalink to &quot;Values that never travel as such&quot;">​</a></h2><ul><li><strong>Encrypted fields</strong> (<code>Field::encrypted</code>, <code>Field::encrypted_map</code>) never carry their value: a record holds a state object (<code>{&quot;state&quot;: &quot;set&quot;}</code>, or the names of a map) and writes send replacements. See <a href="./../admin/forms.html#encrypted-fields">Encrypted fields</a>.</li><li><strong>Rich text</strong> is a <code>Json</code> column holding a closed, versioned document, validated and bounded on the server; HTML is never stored. See <a href="./../admin/media.html#rich-text">Rich text</a>.</li><li><strong>Fields the user may not read</strong> are absent from <code>data</code>; undeclared columns are never sent. The one exception is an encrypted field the user may only write: on a record they may view it is sent as its masked state, never its value or a map&#39;s names.</li></ul><h2 id="unsupported-column-types" tabindex="-1">Unsupported column types <a class="header-anchor" href="#unsupported-column-types" aria-label="Permalink to &quot;Unsupported column types&quot;">​</a></h2><p>These column types have no kind, so they cannot be admin fields. Declaring a field on one stops the boot (<code>unknown or unsupported column</code>); a column of such a type that is not declared as a field is simply left out.</p><ul><li><code>smallint</code>, <code>tinyint</code> (Rust <code>i16</code>, <code>i8</code>) and every unsigned type (<code>u8</code> … <code>u64</code>): use <code>integer</code> or <code>bigint</code>;</li><li><code>time</code> without a date, <code>interval</code>;</li><li>binary columns (<code>binary</code>, <code>varbinary</code>, <code>blob</code>, <code>bytea</code>);</li><li>enums (database <code>ENUM</code> types) and arrays: store an enum as a string and bound it in a hook;</li><li>network, geometric and other database-specific types.</li></ul><p>JSON columns edited in a browser cannot hold integers beyond ±2⁵³ exactly: store large identifiers as strings.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./admin-api.html">Admin API</a></li><li><a href="./../basics/errors.html">Errors</a> and <a href="./error-codes.html">Error codes</a></li><li><a href="./../admin/custom-fields.html">Custom fields</a></li><li><a href="./limitations.html">Limitations</a></li></ul>',19)])])}const p=t(r,[["render",c]]);export{m as __pageData,p as default};
